package oauth2

import (
	"encoding/hex"
	"errors"
	"strings"
)

// gitlabTokenPrefixes lists standard token prefixes generated by GitLab.
var gitlabTokenPrefixes = []string{
	"glcbt-",
	"gldt-",
	"glrt-",
	"glrtr-",
	"glft-",
	"glptt-",
	"glimt-",
	"glagent-",
	"glsoat-",
	"glffct-",
	"glwt-",
}

// validateTokenPrefix detects common mistake values such as personal access tokens (glpat-)
// or application secrets (gloas-) and returns descriptive error messages.
func validateTokenPrefix(clientID string) error {
	trimmed := strings.TrimSpace(clientID)
	lower := strings.ToLower(trimmed)
	if strings.HasPrefix(lower, "glpat-") {
		return errors.New("value is a personal access token (glpat-), not an OAuth application ID")
	}
	if strings.HasPrefix(lower, "gloas-") {
		return errors.New("value is an OAuth application secret (gloas-), not the Application ID (glab is a public client and does not use a secret)")
	}
	for _, prefix := range gitlabTokenPrefixes {
		if strings.HasPrefix(lower, prefix) {
			return errors.New("value appears to be a GitLab token, not an OAuth application ID")
		}
	}

	return nil
}

// ValidateClientID checks that clientID is a 64-character hexadecimal string
// as generated by GitLab OAuth Application registrations.
// It also detects common mistake values such as personal access tokens (glpat-)
// or application secrets (gloas-) and returns descriptive error messages.
func ValidateClientID(clientID string) error {
	trimmed := strings.TrimSpace(clientID)
	if trimmed == "" {
		return errors.New("OAuth application ID cannot be empty")
	}

	if err := validateTokenPrefix(trimmed); err != nil {
		return err
	}

	if len(trimmed) != 64 {
		return errors.New("OAuth application ID must be 64 hexadecimal characters")
	}

	if _, err := hex.DecodeString(trimmed); err != nil {
		return errors.New("OAuth application ID must be 64 hexadecimal characters")
	}

	return nil
}
